import moment from 'moment-timezone';

export const TIME_IN_SECONDS = Object.freeze({
  DAY: 86400,
  HOUR: 3600,
  MINUTE: 60,
  MONTH: 2592000,
  WEEK: 604800,
});

export const DEFAULT_TIMESTAMP_FORMAT = 'ddd MMM D, YYYY h:mm a z';
export const DATE_MASK = 'MM/DD/YYYY';
export const TIME_MASK = 'hh:mm a';
export const UPPER_DATE_LIMIT_VALUE = '2038-01-19T03:14:07Z'; // https://en.wikipedia.org/wiki/Year_2038_problem
export const DATE_TIME_MASK = 'MM/DD/YYYY hh:mm A';

/**
 * Converts a timestamp and timezone to the given timezone, else UTC if null
 * @param {number} timestamp The timestamp string
 * @param {string} timezone The string timezone, like America/Denver
 * @param {string} format The custom format
 *
 * @returns {string} Moment time string
 */
export function formatTimestamp(
  timestamp,
  timezone = 'UTC',
  format = DEFAULT_TIMESTAMP_FORMAT,
) {
  if (!timestamp) {
    return '';
  }
  const unixTimestamp = moment(timestamp, 'X');

  return unixTimestamp.tz(timezone).format(format);
}

/**
 * Converts the given amount of time into seconds
 * @param {number} time amount of time for the given unit
 * @param {string | null} unit unit of time
 * @returns {number} time in seconds
 */
export function convertToSeconds(time, unit) {
  if (!unit) {
    return time;
  }

  switch (unit.toLocaleLowerCase()) {
    case 'days':
      return time * TIME_IN_SECONDS.DAY;
    case 'hours':
      return time * TIME_IN_SECONDS.HOUR;
    case 'minutes':
      return time * TIME_IN_SECONDS.MINUTE;
    default:
      return time;
  }
}
